import 'package:flutter/material.dart';
import '../app_state.dart';

class OrderDetailPage extends StatelessWidget {
 final int? orderId;
 const OrderDetailPage({super.key,this.orderId});
 @override Widget build(BuildContext context)=>AnimatedBuilder(animation:AppState.instance,builder:(context,_) {final all=AppState.instance.orders;final matches=all.where((o)=>orderId==null||o.id==orderId);final order=matches.isEmpty?null:matches.first;return Scaffold(appBar:AppBar(title:const Text('Detail Pesanan')),body:order==null?const Center(child:Text('Pesanan tidak ditemukan.')):ListView(padding:const EdgeInsets.all(20),children:[const Icon(Icons.receipt_long,color:Colors.deepOrange,size:64),const SizedBox(height:14),Center(child:Text('Pesanan #${order.id.toString().substring(order.id.toString().length-5)}',style:const TextStyle(fontSize:22,fontWeight:FontWeight.bold))),const SizedBox(height:8),Center(child:Text(order.status,style:const TextStyle(color:Colors.deepOrange,fontWeight:FontWeight.bold))),const Divider(height:32),const ListTile(leading:Icon(Icons.restaurant),title:Text('Orangtua Delivery'),subtitle:Text('Pesanan makanan')),ListTile(leading:const Icon(Icons.payments_outlined),title:const Text('Total pembayaran'),trailing:Text('Rp${_money(order.total)}',style:const TextStyle(fontWeight:FontWeight.bold,fontSize:17))),const SizedBox(height:16),const Text('Tahapan pesanan',style:TextStyle(fontSize:18,fontWeight:FontWeight.bold)),...['Pesanan dibuat','Diterima restoran','Sedang disiapkan','Dalam perjalanan','Selesai'].map((s)=>ListTile(leading:Icon(s==order.status?Icons.radio_button_checked:Icons.circle_outlined,color:s==order.status?Colors.deepOrange:Colors.grey),title:Text(s))),const SizedBox(height:12),const Text('Status ini adalah simulasi lokal, belum terhubung ke restoran atau kurir sungguhan.',style:TextStyle(color:Colors.grey,fontSize:12))]));});
 String _money(int n)=>n.toString().replaceAllMapped(RegExp(r'\B(?=(\d{3})+(?!\d))'),(_)=>'.');
}
